import{_ as t,C as a,o,c as s,E as n,a2 as i}from"./chunks/framework.BOeh4kYD.js";const m=JSON.parse('{"title":"重试成功，不等于恢复可信","description":"","frontmatter":{"title":"重试成功，不等于恢复可信","date":"2026-09-15","column":"open-source-engineering","category":"daily","article_type":"engineering-insight","edition":"research-center","research_question":"智能体工作流在首次失败后恢复时，必须分别保存哪些事实，才能证明恢复有效、正确且安全，而不只是后来一次尝试成功？","summary":"结构化基准显示，可靠的失败信号加一次有界修正可以挽回大量首次失败，复杂反馈在该环境中的额外价值有限。但一次后续成功无法证明语义正确、外部效果安全或授权仍有效，恢复必须按阶段分别取证。","sources":["research/analysis/Q-20260915-02-phase-separated-recovery-evidence.md"],"item_id":"Q-20260915-02","lifecycle":"Published","cover":"/assets/covers/daily-2026-09-15-successful-retry-not-trustworthy-recovery-cover.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"zh/engineering/2026-09-15-successful-retry-not-trustworthy-recovery.md","filePath":"zh/engineering/2026-09-15-successful-retry-not-trustworthy-recovery.md","lastUpdated":1789473899000}'),l={name:"zh/engineering/2026-09-15-successful-retry-not-trustworthy-recovery.md"};function c(p,e,h,u,d,g){const r=a("ArticleCover");return o(),s("div",null,[n(r,{image:"/assets/covers/daily-2026-09-15-successful-retry-not-trustworthy-recovery-cover.png",kicker:"开源工程 · 每日研究",title:"重试成功，不等于恢复可信",summary:"结构化基准显示，可靠的失败信号加一次有界修正可以挽回大量首次失败，复杂反馈在该环境中的额外价值有限。但一次后续成功无法证明语义正确、外部效果安全或授权仍有效，恢复必须按阶段分别取证。",version:"Q-20260915-02",status:"Daily Runtime V5 · 2026-09-15",languageHref:"/en/engineering/2026-09-15-successful-retry-not-trustworthy-recovery",languageLabel:"English"}),e[0]||(e[0]=i('<h1 id="重试成功-不等于恢复可信" tabindex="-1">重试成功，不等于恢复可信 <a class="header-anchor" href="#重试成功-不等于恢复可信" aria-label="Permalink to &quot;重试成功，不等于恢复可信&quot;">​</a></h1><p>一个 Agent（智能体）调用外部工具后超时。第二次调用返回成功，于是运行时把任务标成“已恢复”。但第一次调用是否已经改变了外部系统？第二次结果是否语义正确？原来的业务授权在重试时是否仍有效？一个成功状态回答不了这些问题。</p><p>恢复不是失败后再试一次，而是一条需要分别取证的路径。检测、路由、修正、预算、验收和外部效果核对必须保留各自身份；终态可以汇总这些事实，不能替代它们。</p><h2 id="基准真正测量了什么" tabindex="-1">基准真正测量了什么 <a class="header-anchor" href="#基准真正测量了什么" aria-label="Permalink to &quot;基准真正测量了什么&quot;">​</a></h2><p>同日研究对象分析了 LAST-CQ（文本到图数据库查询恢复基准）。研究覆盖六种模型骨干与2471个实时数据库查询，任务是把自然语言转成 Cypher（图数据库查询语言），并在 Neo4j（图数据库系统）环境中验证和执行。</p><p>流程先确定性解析模式，再生成首次查询。验证阶段使用解释检查与受限执行；发现失败后，系统解析环境错误，可选择生成更丰富的反馈，然后把一次有界修正交给后续执行。这样的拆分让研究能比较恢复的不同组件，而不是把“自我纠正”当作一个不可解释能力。</p><p>论文报告，进入修正路径的首次失败在六种模型上的未加权平均恢复率为91.7%，汇总恢复率为93.8%。这是有力但有范围的证据：在可执行、结构化且失败信号明确的环境中，一次受环境约束的修正能够挽回大量失败。</p><h2 id="更复杂反思在这里增益很小" tabindex="-1">更复杂反思在这里增益很小 <a class="header-anchor" href="#更复杂反思在这里增益很小" aria-label="Permalink to &quot;更复杂反思在这里增益很小&quot;">​</a></h2><p>最有工程价值的消融不是“恢复有效”，而是“哪一部分有效”。把合成的结构化反馈替换为原始数据库错误后，总体精确匹配只发生约一个百分点的变化。</p><p>这意味着，在该基准里，大部分价值可能来自三个简单事实：目标环境明确指出首次尝试失败；工作流真的进入修正路线；系统允许另一次受证据约束的尝试。更长、更像解释的反馈不是主要贡献者。</p><p>结论不能外推成“反思无用”。文本到查询拥有明确模式和可执行错误，许多浏览器、谈判或规划失败却是隐性的、语义性的。合理的工程顺序是先测量原始错误加有界重试的基线，再要求更复杂诊断证明增量价值。</p><h2 id="更多尝试不是同一种机制" tabindex="-1">更多尝试不是同一种机制 <a class="header-anchor" href="#更多尝试不是同一种机制" aria-label="Permalink to &quot;更多尝试不是同一种机制&quot;">​</a></h2><p>研究还比较了相近生成预算下的并行三样本选择。额外候选没有环境失败证据来连接各次尝试，报告结果弱于执行环境驱动的迭代修正。</p><p>这里的区别不只是串行与并行，而是信息结构。一个修正路径知道前一次在哪里、以何种方式失败；独立采样只增加候选数量。相同调用预算并不意味着相同恢复能力。</p><p>因此，恢复预算至少要记录尝试编号、最大次数、串行或并行策略、成本时间约束，以及继续尝试的理由。否则，团队只会看到“用了三次调用”，却无法判断预算买到的是新信息还是更多猜测。</p><h2 id="六种恢复身份必须分开" tabindex="-1">六种恢复身份必须分开 <a class="header-anchor" href="#六种恢复身份必须分开" aria-label="Permalink to &quot;六种恢复身份必须分开&quot;">​</a></h2><p>一份可审计的恢复记录应包含六个阶段。</p><ul><li><strong>失败检测</strong>：哪个操作失败，由哪个环境或验证者检测，原始失败证据是什么；</li><li><strong>恢复路由</strong>：选择重试、修复、补偿、升级、放弃还是人工复核，使用哪一版策略；</li><li><strong>修正输入</strong>：哪些内容是环境观察，哪些是模型解释，新增事实从哪里来；</li><li><strong>重试预算</strong>：当前第几次、上限多少、时间与成本边界是什么；</li><li><strong>结果验收</strong>：执行、语义、策略和安全检查分别由谁完成，保留什么不确定性；</li><li><strong>效果核对</strong>：前一次是否产生外部效果，状态是未发生、已发生、已补偿还是未知。</li></ul><p>一个“已恢复”字段只能成为这些事实的摘要。后续尝试成功不能倒推首次检测正确，也不能抹去第一次可能已经发生的效果。</p><h2 id="可执行不等于正确" tabindex="-1">可执行不等于正确 <a class="header-anchor" href="#可执行不等于正确" aria-label="Permalink to &quot;可执行不等于正确&quot;">​</a></h2><p>研究本身提供了重要负面证据：非空执行不是语义正确。论文同时使用精确匹配、文本相似度和模型评审，并指出模型评审相对人工校准偏乐观。</p><p>失败类别的恢复也高度不均。模式违规的恢复率远高于语法和类型错误；一个模型可以拥有很高的失败恢复比例，却在另一项总体质量指标上出现小幅退化。单一百分比会遮住这种差异。</p><p>验收门因此必须与风险匹配。查询类任务可以把可执行性作为一项信号，但结果会影响决策时，还需要语义检查、权限范围与不确定性记录。工具返回了内容，只能证明调用结束，不能证明结果值得采用。</p><h2 id="重放前必须先核对外部效果" tabindex="-1">重放前必须先核对外部效果 <a class="header-anchor" href="#重放前必须先核对外部效果" aria-label="Permalink to &quot;重放前必须先核对外部效果&quot;">​</a></h2><p>数据库查询基准没有证明任意外部动作都能安全重试。生产智能体可能在收到超时前已经发送消息、创建订单或修改记录。若系统把超时直接解释为“没有效果”，第二次调用会制造重复动作。</p><p>对会改变状态的工具，效果核对应早于重试。稳定的操作身份、幂等键、外部回执和补偿能力可以把“未知”缩小为可判断状态；无法判断时，应升级人工或停止，而不是盲目重放。</p><p>业务授权也不能从第一次尝试继承。任务目标、收件人、金额、审批或策略可能在故障期间变化。恢复路线解决的是技术故障，动作边界仍需重新读取当前权威。</p><h2 id="恢复策略取决于失败类型" tabindex="-1">恢复策略取决于失败类型 <a class="header-anchor" href="#恢复策略取决于失败类型" aria-label="Permalink to &quot;恢复策略取决于失败类型&quot;">​</a></h2><p>低风险、只读、失败明确且验收确定的操作，适合一次成本较低的有界重试。模式不存在、参数无效等确定性问题，若输入未改变，重复调用可能没有意义；需要先修正。语义模糊的输出需要更强验收。副作用未知的操作则应优先核对、补偿或人工决策。</p><p>这比统一“重试三次”复杂，但它保存了真正决定安全性的条件：失败是否可观察，修正是否有依据，结果能否验收，之前的效果是否已发生，以及当前是否仍有权执行。</p><h2 id="边界与未决问题" tabindex="-1">边界与未决问题 <a class="header-anchor" href="#边界与未决问题" aria-label="Permalink to &quot;边界与未决问题&quot;">​</a></h2><p>当前证据属于文本到图数据库查询，显式模式与可执行反馈使错误比一般工具更可观察。一些变体来自既有轨迹的反事实重评分，模型评审也不是事实真值。研究没有建立跨数据库引擎、浏览器或有副作用接口的通用结果，也没有系统测量生产时延与令牌成本。</p><p>仍需回答：哪些失败类型足够确定，适合自动重试；怎样检测可执行但语义错误的结果；复杂诊断何时值得增加；效果未知时什么证据足以继续；重试预算怎样随成本与风险变化。</p><p>有界结论是：<strong>可靠检测、明确路由和一次有环境证据的修正，在结构化领域可能获得大部分可恢复价值；但可信恢复还必须分别证明验收、外部效果与当前授权。第二次成功只是恢复路径中的一项证据，不是整条路径的证明。</strong></p><p><strong>证据与来源：</strong></p><ul><li><a href="https://arxiv.org/abs/2609.12746" target="_blank" rel="noreferrer">LAST-CQ 论文与执行环境恢复实验</a>，2026。</li></ul>',36))])}const _=t(l,[["render",c]]);export{m as __pageData,_ as default};
